/**
 * Optional rule "Efeitos da mesma habilidade" (#27).
 *
 * By the book (chapter 5, "Acumulando Efeitos"), effects of abilities stack, except effects of the same ability.
 * The system stamps chat card effects with `origin = actor.uuid` only, so it cannot tell where an effect came from.
 * This rule stamps every effect generated by using a "poder" item with the ability identity (compendium source or
 * item name, plus the effect name), and, when such an effect is created on an actor that already has one with the
 * same identity, either replaces the previous one or keeps the greater one. The GM picks off (default), replace
 * or highest.
 */
import { MODULE_ID, markWrapper } from "../utils.mjs";

export const SAME_ABILITY_SETTING = "sameAbilityStackingRule";
export const SAME_ABILITY_FLAG = "ability";
export const SAME_ABILITY_MODES = ["off", "replace", "highest"];

/**
 * Identity of an ability effect: the same for every actor that has the ability.
 * @param {{compendiumSource?: string|null, itemName?: string, effectName?: string, slugify?: (s: string) => string}} p
 * @returns {string}  Empty when there is not enough data.
 */
export function abilityIdentity({ compendiumSource, itemName, effectName, slugify = (s) => s }) {
  const effect = String(effectName ?? "").trim();
  if (!effect) return "";
  if (compendiumSource) return `${compendiumSource}#${effect}`;
  const name = String(itemName ?? "").trim();
  if (!name) return "";
  return `Item:${slugify(name)}#${effect}`;
}

/**
 * @template T
 * @param {T[]} existing
 * @param {string} identity
 * @param {(entry: T) => unknown} identityOf
 * @returns {T[]}
 */
export function findSameAbility(existing, identity, identityOf = (e) => e?.identity) {
  if (!identity) return [];
  return (existing ?? []).filter((entry) => identityOf(entry) === identity);
}

/** Numeric value of a change, or NaN. Blank values are not numbers. */
function numeric(value) {
  if (typeof value === "number") return value;
  if (typeof value !== "string" || !value.trim()) return NaN;
  return Number(value);
}

/**
 * Magnitude of an effect: the sum of the numeric values of its changes (keys starting with "@" are roll data, not
 * bonuses). Any other non-numeric value (a die, a formula, a flag) makes the effect incomparable (NaN). A single
 * number per effect keeps the comparison transitive, so concurrent reconciliations agree on the greatest effect.
 * @param {{key: string, value: unknown}[]} changes
 * @returns {number}
 */
export function magnitudeScore(changes) {
  let total = 0;
  for (const change of changes ?? []) {
    const key = change?.key;
    if (typeof key !== "string" || !key || key.startsWith("@")) continue;
    total += numeric(change.value);
  }
  return total;
}

/**
 * Compares two effects by magnitude (see magnitudeScore). An incomparable effect, or equal magnitudes, is a tie.
 * @param {{key: string, value: unknown}[]} changesA
 * @param {{key: string, value: unknown}[]} changesB
 * @returns {-1|0|1}
 */
export function compareMagnitude(changesA, changesB) {
  const a = magnitudeScore(changesA);
  const b = magnitudeScore(changesB);
  if (!Number.isFinite(a) || !Number.isFinite(b) || a === b) return 0;
  return a > b ? 1 : -1;
}

/**
 * @param {string} policy  One of SAME_ABILITY_MODES.
 * @param {{previous: boolean, comparison?: number|null}} state  Whether the target has an effect of the same ability
 *   and, for "highest", the comparison of the new effect against the greatest active one (null = none active).
 * @returns {"allow"|"replace"|"refuse"}
 */
export function decideStacking(policy, { previous, comparison = null } = {}) {
  if (!previous || !SAME_ABILITY_MODES.includes(policy) || policy === "off") return "allow";
  if (policy === "highest" && comparison !== null && comparison <= 0) return "refuse";
  return "replace";
}

/**
 * Reconciles the effects of one ability on one actor after an effect was created, so concurrent applications
 * (double clicks, several users) converge to one survivor whatever each client saw. Every reconciliation uses the
 * same total order (server creation time, then id) and a survivor rule that never changes when more effects are
 * seen: the last one ("replace") or the first of the greatest active ones by magnitudeScore ("highest"). The creator of the new
 * effect deletes everything but the survivor of its own view; the global survivor is never deleted, because no
 * view can contain a greater one, and every other effect is deleted by its own creator or by a later one.
 * @param {string} policy
 * @param {string} selfId  The effect just created by this user.
 * @param {{id: string, createdTime?: number, disabled?: boolean, changes?: object[]}[]} entries  Every effect of the
 *   ability on the actor, including the new one.
 * @returns {{remove: string[], selfRemoved: boolean}}
 */
export function planReconcile(policy, selfId, entries) {
  const none = { remove: [], selfRemoved: false };
  const time = (e) => Number(e.createdTime) || 0;
  const sorted = [...(entries ?? [])].sort((a, b) => {
    if (time(a) !== time(b)) return time(a) - time(b);
    return String(a.id) < String(b.id) ? -1 : String(a.id) > String(b.id) ? 1 : 0;
  });
  const self = sorted.find((e) => e.id === selfId);
  if (!self || sorted.length < 2 || policy === "off" || !SAME_ABILITY_MODES.includes(policy)) return none;
  let survivor = sorted.at(-1);
  if (policy === "highest") {
    // Rank: active before disabled, then magnitude (incomparable lowest), then the total order. A strict total order,
    // so the survivor of any view is the greatest effect it contains.
    const rank = (e) => (e.disabled ? -Infinity : Number.isFinite(magnitudeScore(e.changes)) ? magnitudeScore(e.changes) : -Number.MAX_VALUE);
    survivor = sorted[0];
    for (const entry of sorted) if (rank(entry) > rank(survivor)) survivor = entry;
  }
  return { remove: sorted.filter((e) => e !== survivor).map((e) => e.id), selfRemoved: survivor !== self };
}

/**
 * Id of the "Sustentando" marker a sustained card effect points to (`<actor uuid>.ActiveEffect.<id>`, T20:6635).
 * @param {unknown} origin
 * @returns {{casterUuid: string, markerId: string}|null}
 */
export function sustainMarker(origin) {
  if (typeof origin !== "string") return null;
  const [casterUuid, markerId, ...rest] = origin.split(".ActiveEffect.");
  if (!casterUuid || !markerId || rest.length) return null;
  return { casterUuid, markerId };
}

/* -------------------------------------------- */
/*  Foundry integration                         */
/* -------------------------------------------- */

const FLAG_PATH = `flags.${MODULE_ID}.${SAME_ABILITY_FLAG}`;

/** Batches seen by _preCreate (the options object is shared by every entry of one operation). */
const batches = new WeakMap();
/**
 * Sustained origins this client is still creating (between _preCreate and createActiveEffect). The card applies to
 * the selected tokens one after the other, and only the active GM creates markers, so the marker of an origin with a
 * pending creation here is never treated as orphan. A creation that never completes keeps its marker (safe side).
 */
const pendingOrigins = new Map();
/** Sustained origins whose marker this client is deleting: a creation with that origin waits, so the system recreates it. */
const deletingMarkers = new Map();

function getPolicy() {
  try {
    const mode = game.settings.get(MODULE_ID, SAME_ABILITY_SETTING);
    return SAME_ABILITY_MODES.includes(mode) ? mode : "off";
  } catch {
    return "off";
  }
}

const identityOf = (effect) => {
  const value = foundry.utils.getProperty(effect ?? {}, FLAG_PATH);
  return typeof value === "string" ? value : "";
};

/** Writes or removes the flag on the instance and on its source; only used on clones, never on live documents. */
function setFlag(effect, identity) {
  for (const target of [effect, effect._source]) {
    if (!target) continue;
    if (identity) {
      target.flags ??= {};
      target.flags[MODULE_ID] ??= {};
      target.flags[MODULE_ID][SAME_ABILITY_FLAG] = identity;
    } else if (target.flags?.[MODULE_ID] && SAME_ABILITY_FLAG in target.flags[MODULE_ID]) {
      delete target.flags[MODULE_ID][SAME_ABILITY_FLAG];
    }
  }
}

/**
 * Stamps the rolled clone's own effects (including the ones linked-usage-effects injects): the system copies
 * `ef.flags` into the chat card effect, and from there into the applied effect. Effects of other item types lose
 * a stamp they may carry (for instance, an effect brewed into a potion), so only "poder" uses take part.
 */
function stampClone(item) {
  if (!item?.effects || !item.isEmbedded || item.actor?.items?.get(item.id) === item) return;
  const isPower = item.type === "poder";
  const source = isPower ? (item._stats?.compendiumSource ?? foundry.utils.getProperty(item, "flags.core.sourceId")) : null;
  const slugify = (s) => (typeof s.slugify === "function" ? s.slugify() : s.toLowerCase());
  for (const effect of item.effects) {
    const identity = isPower ? abilityIdentity({ compendiumSource: source, itemName: item.name, effectName: effect.name, slugify }) : "";
    setFlag(effect, identity);
  }
}

function changesOf(effect) {
  const changes = effect?.system?.changes ?? effect?._source?.system?.changes;
  return Array.isArray(changes) ? changes : [];
}

/** Notification text; every message cites the official rule ("Acumulando Efeitos"). */
function ruleMessage(key, effect, actor) {
  const reference = game.i18n.localize("T20CP.SameAbility.Reference");
  return game.i18n.format(`T20CP.SameAbility.${key}`, { effect: effect?.name, actor: actor?.name, reference });
}

/**
 * Runs before ActiveEffect#_preCreate, so a refused effect never reaches the system's side effects (such as the
 * "Sustentando" marker the active GM creates for a sustained effect). Returns false to refuse.
 */
function checkCreation(effect, data, options) {
  const policy = getPolicy();
  if (policy === "off") return;
  const identity = foundry.utils.getProperty(data ?? {}, FLAG_PATH);
  const actor = effect?.parent;
  if (typeof identity !== "string" || !identity || actor?.documentName !== "Actor") return;

  if (options && typeof options === "object") {
    let batch = batches.get(options);
    if (!batch) batches.set(options, (batch = new Set()));
    if (batch.has(identity)) {
      console.warn(`${MODULE_ID} | same-ability-stacking: "${effect.name}" twice in one creation; only the first is kept`);
      return false;
    }
    batch.add(identity);
  }

  const previous = findSameAbility([...(actor.effects ?? [])], identity, identityOf);
  let comparison = null;
  if (policy === "highest") {
    const newChanges = Array.isArray(data?.system?.changes) ? data.system.changes : changesOf(effect);
    for (const old of previous) {
      if (old.disabled) continue;
      const result = compareMagnitude(newChanges, changesOf(old));
      comparison = comparison === null ? result : Math.min(comparison, result);
    }
  }
  if (decideStacking(policy, { previous: previous.length > 0, comparison }) === "refuse") {
    ui.notifications?.warn(ruleMessage("Refused", effect, actor));
    return false;
  }
}

function trackPending(data, delta) {
  const origin = data?.duration?.expiry === "sustainEnd" ? data.origin : null;
  if (typeof origin !== "string" || !origin) return;
  const count = (pendingOrigins.get(origin) ?? 0) + delta;
  if (count > 0) pendingOrigins.set(origin, count);
  else pendingOrigins.delete(origin);
}

/** createActiveEffect: the creating user reconciles the effects of the ability on the actor. */
function onCreate(effect, options, userId) {
  if (userId !== game.user?.id) return;
  trackPending(effect, -1);
  const policy = getPolicy();
  if (policy === "off") return;
  const identity = identityOf(effect);
  const actor = effect?.parent;
  if (!identity || actor?.documentName !== "Actor") return;
  const entries = findSameAbility([...(actor.effects ?? [])], identity, identityOf).map((e) => ({
    id: e.id,
    createdTime: e._stats?.createdTime,
    disabled: !!e.disabled,
    changes: changesOf(e)
  }));
  const { remove, selfRemoved } = planReconcile(policy, effect.id, entries);
  const ids = remove.filter((id) => actor.effects?.has(id));
  if (!ids.length) return;
  if (selfRemoved && policy === "highest") ui.notifications?.warn(ruleMessage("Refused", effect, actor));
  else ui.notifications?.info(ruleMessage("Replaced", effect, actor));
  actor
    .deleteEmbeddedDocuments("ActiveEffect", ids)
    .then(() => (selfRemoved ? removeOrphanMarker(effect) : undefined))
    .catch((err) => {
      console.warn(`${MODULE_ID} | same-ability-stacking: failed to delete the replaced effects`, err);
    });
}

/** Actors that may hold card effects: world actors and the synthetic actors of unlinked tokens in every scene. */
function* candidateActors() {
  yield* game.actors ?? [];
  for (const scene of game.scenes ?? []) {
    for (const token of scene.tokens ?? []) {
      if (!token.actorLink && token.actor) yield token.actor;
    }
  }
}

/**
 * A sustained effect removed by the reconciliation may leave the "Sustentando" marker the active GM created for it
 * in ActiveEffectT20#_preCreate. Only the active GM creates markers, so only it removes one, and only when no other
 * effect still points to the same origin (one card can apply the same origin to several targets).
 */
async function removeOrphanMarker(effect) {
  if (!game.user?.isActiveGM || effect?.duration?.expiry !== "sustainEnd") return;
  const marker = sustainMarker(effect.origin);
  if (!marker || pendingOrigins.has(effect.origin)) return;
  for (const other of candidateActors()) {
    for (const e of other.effects ?? []) if (e.id !== effect.id && e.origin === effect.origin) return;
  }
  const caster = foundry.utils.fromUuidSync(marker.casterUuid);
  const doc = caster?.effects?.get(marker.markerId);
  if (!doc) return;
  const deletion = Promise.resolve()
    .then(() => doc.delete())
    .finally(() => {
      if (deletingMarkers.get(effect.origin) === deletion) deletingMarkers.delete(effect.origin);
    });
  deletingMarkers.set(effect.origin, deletion);
  await deletion;
}

/** Registers the world setting. Runs on "init" for every system, so the setting always exists. */
export function registerSameAbilitySetting() {
  game.settings.register(MODULE_ID, SAME_ABILITY_SETTING, {
    name: "T20CP.SameAbility.Setting.Name",
    hint: "T20CP.SameAbility.Setting.Hint",
    scope: "world",
    config: false,
    type: String,
    choices: {
      off: "T20CP.SameAbility.Setting.off",
      replace: "T20CP.SameAbility.Setting.replace",
      highest: "T20CP.SameAbility.Setting.highest"
    },
    default: "off"
  });
}

/**
 * Installs the rule. Must run after the patches, so the stamp sees the effects linked-usage-effects injects.
 * The stamp is always applied (it is inert), so effects applied while the rule is off are recognized later.
 */
export function installSameAbilityRule() {
  const proto = CONFIG.Item?.documentClass?.prototype;
  const original = proto?._allApplicableOnUseEffects;
  if (typeof original !== "function") throw new Error("Tormenta20 usage effect API not found");
  proto._allApplicableOnUseEffects = markWrapper(function (...args) {
    const effects = original.apply(this, args);
    try {
      stampClone(this);
    } catch (err) {
      console.error(`${MODULE_ID} | same-ability-stacking: failed to stamp the ability effects`, err);
    }
    return effects;
  }, original);
  const effectProto = CONFIG.ActiveEffect?.documentClass?.prototype;
  const preCreate = effectProto?._preCreate;
  if (typeof preCreate !== "function") throw new Error("ActiveEffect#_preCreate not found");
  effectProto._preCreate = markWrapper(function (...args) {
    let allowed;
    try {
      allowed = checkCreation(this, args[0], args[1]);
    } catch (err) {
      console.error(`${MODULE_ID} | same-ability-stacking: failed to check the effect`, err);
    }
    if (allowed === false) return Promise.resolve(false);
    trackPending(args[0], 1);
    const deletion = args[0]?.duration?.expiry === "sustainEnd" ? deletingMarkers.get(args[0].origin) : undefined;
    if (!deletion) return preCreate.apply(this, args);
    return deletion.catch(() => {}).then(() => preCreate.apply(this, args));
  }, preCreate);
  Hooks.on("createActiveEffect", (effect, options, userId) => {
    try {
      onCreate(effect, options, userId);
    } catch (err) {
      console.error(`${MODULE_ID} | same-ability-stacking: failed to replace the previous effect`, err);
    }
  });
}
